const MINIMAX_M31_MODEL_ID=`MiniMax-M3.1-Flash`;const MINIMAX_M31_PREVIEW_MODEL_ID=`MiniMax-M3.1-Flash-Preview`;const BUDGET_THINKING_LEVELS=[`off`,`minimal`,`low`,`medium`,`high`];const ADAPTIVE_THINKING_LEVELS=[`off`,`adaptive`];const MINIMAX_M31_THINKING_LEVELS=[`low`,`medium`,`high`,`xhigh`,`max`];function isMinimaxM31ModelId(e){const t=e.trim().toLowerCase();return[MINIMAX_M31_MODEL_ID,MINIMAX_M31_PREVIEW_MODEL_ID].some(e=>e.toLowerCase()===t)}function resolveMinimaxThinkingProfile(e){if(isMinimaxM31ModelId(e))return{levels:MINIMAX_M31_THINKING_LEVELS.map(e=>({id:e})),defaultLevel:`max`};if(/^MiniMax-M3(\b|[-.])/i.test(e))return{levels:ADAPTIVE_THINKING_LEVELS.map(e=>({id:e})),defaultLevel:`adaptive`};if(/^MiniMax-M2(?:\b|[-.])/i.test(e))return{levels:BUDGET_THINKING_LEVELS.map(e=>({id:e})),defaultLevel:`off`}}export{resolveMinimaxThinkingProfile as a,isMinimaxM31ModelId as i,MINIMAX_M31_PREVIEW_MODEL_ID as n,MINIMAX_M31_THINKING_LEVELS as r,MINIMAX_M31_MODEL_ID as t};